1	import { execSync } from "node:child_process";
2	import { existsSync, readFileSync, realpathSync, mkdirSync, copyFileSync, writeFileSync, readdirSync, unlinkSync } from "node:fs";
3	import { join } from "node:path";
4	import { homedir, hostname } from "node:os";
5	import { readConfig } from "../commands/config.js";
6	import type { HookInput, RepoState, HookPlan, SyncPlan, ClockInPlan, Timecard, RuntimeContext } from "./hook-types.js";
7	import { HOOK_EXPLAINER } from "./hook-types.js";
8	import { extractTaskFromTranscript, buildCommitPlanWithTask, classifyTimecards, formatClockInMessage, formatSessionStartSummary } from "./hook-plan.js";
9	
10	/** Absent a `target-branch` override in `.trunk-sync/config`, agents sync to a dedicated branch — not the repo's actual default branch — so auto-commits never land directly on it. */
11	const DEFAULT_TARGET_BRANCH = "agents";
12	
13	/**
14	 * Gather the current git repo state needed for planning.
15	 * Runs git commands — this is the I/O boundary.
16	 */
17	export function gatherRepoState(input: HookInput): RepoState | null {
18	  const filePath = input.tool_input.file_path ?? null;
19	
20	  let repoRoot: string;
21	  let gitDir: string;
22	  try {
23	    const [toplevel, dir] = execSync("git rev-parse --show-toplevel --git-dir", { encoding: "utf-8" }).trim().split("\n");
24	    repoRoot = toplevel;
25	    gitDir = dir;
26	  } catch {
27	    return null; // not in a git repo
28	  }
29	
30	  let insideRepo = true;
31	  let gitignored = false;
32	  let relPath: string | null = null;
33	
34	  if (filePath) {
35	    // Resolve symlinks so /var/... matches /private/var/... on macOS
36	    const resolvedFile = existsSync(filePath) ? realpathSync(filePath) : filePath;
37	    insideRepo = resolvedFile.startsWith(repoRoot + "/");
38	    if (insideRepo) {
39	      relPath = resolvedFile.slice(repoRoot.length + 1);
40	      try {
41	        execSync(`git check-ignore -q -- "${filePath}"`, { stdio: "ignore" });
42	        gitignored = true;
43	      } catch {
44	        gitignored = false;
45	      }
46	    }
47	  }
48	
49	  let hasRemote = false;
50	  try {
51	    execSync("git remote get-url origin", { stdio: "ignore" });
52	    hasRemote = true;
53	  } catch {
54	    // no remote
55	  }
56	
57	  let targetBranch = "";
58	  if (hasRemote) {
59	    targetBranch = readConfig(repoRoot).get("target-branch") ?? DEFAULT_TARGET_BRANCH;
60	  }
61	
62	  let currentBranch = "";
63	  const headContent = readFileSync(join(gitDir, "HEAD"), "utf-8").trim();
64	  if (headContent.startsWith("ref: refs/heads/")) {
65	    currentBranch = headContent.slice("ref: refs/heads/".length);
66	  }
67	
68	  const inMerge = existsSync(join(gitDir, "MERGE_HEAD"));
69	
70	  let hasStagedChanges = false;
71	  try {
72	    execSync("git diff --cached --quiet", { stdio: "ignore" });
73	  } catch {
74	    hasStagedChanges = true;
75	  }
76	
77	  let deletedFiles: string[] = [];
78	  let modifiedFiles: string[] = [];
79	  if (!filePath) {
80	    try {
81	      const deleted = execSync(`git -C "${repoRoot}" ls-files --deleted`, {
82	        encoding: "utf-8",
83	      }).trim();
84	      if (deleted) deletedFiles = deleted.split("\n");
85	    } catch {
86	      // ignore
87	    }
88	    try {
89	      const modified = execSync(`git -C "${repoRoot}" diff --name-only`, {
90	        encoding: "utf-8",
91	      }).trim();
92	      if (modified) {
93	        // Exclude files already in deletedFiles (diff --name-only includes deletions)
94	        const deletedSet = new Set(deletedFiles);
95	        modifiedFiles = modified.split("\n").filter((f) => !deletedSet.has(f));
96	      }
97	    } catch {
98	      // ignore
99	    }
100	  }
101	
102	  return {
103	    repoRoot,
104	    gitDir,
105	    relPath,
106	    insideRepo,
107	    gitignored,
108	    hasRemote,
109	    targetBranch,
110	    currentBranch,
111	    inMerge,
112	    hasStagedChanges,
113	    deletedFiles,
114	    modifiedFiles,
115	  };
116	}
117	
118	// --- Presence: clock-in (heartbeat) and reaping ---
119	
120	export function getRuntimeContext(): RuntimeContext {
121	  return { hostname: hostname() };
122	}
123	
124	/** Clock in: write or update this agent's timecard on the timeclock. */
125	export function clockIn(repoRoot: string, plan: ClockInPlan, task: string | null): void {
126	  const dir = join(repoRoot, ".trunk-sync", "timeclock");
127	  mkdirSync(dir, { recursive: true });
128	  const filePath = join(repoRoot, plan.timecardPath);
129	  // Preserve clockedInAt and agent-authored progress from existing timecard if present
130	  let timecard = { ...plan.timecard, task };
131	  try {
132	    const existing = JSON.parse(readFileSync(filePath, "utf-8")) as Timecard;
133	    if (existing.clockedInAt) {
134	      timecard = { ...timecard, clockedInAt: existing.clockedInAt };
135	    }
136	    timecard = {
137	      ...timecard,
138	      lastStep: existing.lastStep ?? null,
139	      remainingSteps: existing.remainingSteps ?? null,
140	    };
141	  } catch {
142	    // No existing file — use plan's clockedInAt and null progress
143	  }
144	  writeFileSync(filePath, JSON.stringify(timecard, null, 2) + "\n");
145	}
146	
147	/** Read all timecards from the timeclock directory. */
148	export function readTimecards(repoRoot: string): Timecard[] {
149	  const dir = join(repoRoot, ".trunk-sync", "timeclock");
150	  if (!existsSync(dir)) return [];
151	  const files = readdirSync(dir).filter((f) => f.endsWith(".json"));
152	  const timecards: Timecard[] = [];
153	  for (const file of files) {
154	    try {
155	      const content = readFileSync(join(dir, file), "utf-8");
156	      timecards.push(JSON.parse(content) as Timecard);
157	    } catch {
158	      // Skip unparseable files
159	    }
160	  }
161	  return timecards;
162	}
163	
164	/**
165	 * Build the session-start message: hand the starting agent its own session id and the
166	 * record-progress instruction, then append the handover roster of active + stale sessions.
167	 * Returns null only when no session id is available.
168	 */
169	export function runSessionStart(repoRoot: string, ownSessionId: string | null): string | null {
170	  if (!ownSessionId) return null;
171	  const intro =
172	    `TRUNK-SYNC SESSION: your session id is ${ownSessionId}. Record your progress as you work and before you pause:\n` +
173	    `  trunk-sync progress ${ownSessionId} --last "<step you just finished>" --next "<steps still to do>"`;
174	  const now = new Date();
175	  const { active, stale } = classifyTimecards(ownSessionId, readTimecards(repoRoot), now);
176	  const roster = formatSessionStartSummary(active, stale, now);
177	  return roster ? `${intro}\n\n${roster}` : intro;
178	}
179	
180	/**
181	 * Heartbeat-only Stop hook: if this session has a timecard, bump its heartbeat and sync it
182	 * so remote readers stay fresh through a long no-edit turn. Never forces the agent (no exit 2).
183	 * No-ops when a recent tool-use sync already refreshed the heartbeat, and creates no card for
184	 * a session that never edited.
185	 */
186	export function runStop(state: RepoState, sessionId: string | null): void {
187	  if (!sessionId) return;
188	  const cardPath = join(state.repoRoot, ".trunk-sync", "timeclock", `${sessionId}.json`);
189	  let card: Timecard;
190	  try {
191	    card = JSON.parse(readFileSync(cardPath, "utf-8")) as Timecard;
192	  } catch {
193	    return; // no card — a session that never edited has no handover to keep alive
194	  }
195	
196	  const age = Date.now() - new Date(card.lastActiveAt).getTime();
197	  if (age < HEARTBEAT_STALE_MS) return; // a recent tool-use sync already refreshed the heartbeat
198	
199	  card.lastActiveAt = new Date().toISOString();
200	  try {
201	    writeFileSync(cardPath, JSON.stringify(card, null, 2) + "\n");
202	    execSync(`git -C "${state.repoRoot}" add -- ".trunk-sync/timeclock/${sessionId}.json"`, { stdio: "ignore" });
203	    execSync(`git -C "${state.repoRoot}" commit -m "auto: heartbeat ${sessionId.slice(0, 8)}"`, {
204	      stdio: "ignore",
205	    });
206	  } catch {
207	    return; // nothing to commit or write failed — best-effort
208	  }
209	
210	  if (state.hasRemote) {
211	    try {
212	      executeSync({ targetBranch: state.targetBranch, currentBranch: state.currentBranch });
213	    } catch {
214	      // best-effort: the next tool-use sync retries; the Stop hook always exits 0
215	    }
216	  }
217	}
218	
219	/** Reap the given (reapable) cards by removing their timecard files; returns removed paths. */
220	export function reapCards(repoRoot: string, ids: string[]): string[] {
221	  const removed: string[] = [];
222	  for (const id of ids) {
223	    const filePath = join(repoRoot, ".trunk-sync", "timeclock", `${id}.json`);
224	    try {
225	      unlinkSync(filePath);
226	      removed.push(filePath);
227	    } catch {
228	      // Already gone
229	    }
230	  }
231	  return removed;
232	}
233	
234	function readThrottleTimestamp(sessionId: string): number | null {
235	  const path = join(tmpdir(), `trunk-sync-clockin-${sessionId}`);
236	  try {
237	    return parseInt(readFileSync(path, "utf-8"), 10);
238	  } catch {
239	    return null;
240	  }
241	}
242	
243	function writeThrottleTimestamp(sessionId: string, now: number): void {
244	  const path = join(tmpdir(), `trunk-sync-clockin-${sessionId}`);
245	  writeFileSync(path, String(now));
246	}
247	
248	function tmpdir(): string {
249	  return process.env.TMPDIR || "/tmp";
250	}
251	
252	const THROTTLE_MS = 5 * 60 * 1000; // 5 minutes
253	
254	/** How stale a heartbeat must be before the Stop hook refreshes and re-syncs it. */
255	const HEARTBEAT_STALE_MS = 30 * 60 * 1000; // 30 minutes — half the active display window
256	
257	/**
258	 * Extract the agent's current task from the transcript (same logic as commit enrichment).
259	 * Returns null if transcript is unavailable or unparseable.
260	 */
261	function extractTask(input: HookInput): string | null {
262	  if (!input.transcript_path) return null;
263	  const expanded = input.transcript_path.replace(/^~/, homedir());
264	  try {
265	    const content = readFileSync(expanded, "utf-8");
266	    return extractTaskFromTranscript(content);
267	  } catch {
268	    return null;
269	  }
270	}
271	
272	/**
273	 * Clock in, reap abandoned cards (heartbeat past the TTL), and check who else is active.
274	 * Returns a message if other agents are active and throttle allows.
275	 */
276	function executeClockIn(
277	  plan: ClockInPlan,
278	  input: HookInput,
279	  state: RepoState,
280	): string | null {
281	  try {
282	    const task = extractTask(input);
283	    clockIn(state.repoRoot, plan, task);
284	    const allTimecards = readTimecards(state.repoRoot);
285	    const now = new Date();
286	    const { active, reapable } = classifyTimecards(
287	      plan.timecard.sessionId,
288	      allTimecards,
289	      now,
290	    );
291	
292	    if (reapable.length > 0) {
293	      reapCards(state.repoRoot, reapable.map((tc) => tc.sessionId));
294	    }
295	
296	    // Stage timeclock directory (timecard + any removals)
297	    const timeclockDir = join(state.repoRoot, ".trunk-sync", "timeclock");
298	    try {
299	      execSync(`git add -- "${timeclockDir}"`, { cwd: state.repoRoot, stdio: "ignore" });
300	    } catch {
301	      // best-effort
302	    }
303	
304	    // The first clock-in of a session always speaks (run the tests, resume WIP);
305	    // the co-worker roster repeats at most once per throttle window.
306	    const lastWarning = readThrottleTimestamp(plan.timecard.sessionId);
307	    const nowMs = now.getTime();
308	    const isFirstClockIn = lastWarning === null;
309	    const throttleElapsed = isFirstClockIn || (nowMs - lastWarning) >= THROTTLE_MS;
310	
311	    if (isFirstClockIn || (active.length > 0 && throttleElapsed)) {
312	      writeThrottleTimestamp(plan.timecard.sessionId, nowMs);
313	      return formatClockInMessage(active, now, isFirstClockIn);
314	    }
315	
316	    return null;
317	  } catch {
318	    // Clock-in is best-effort — never fail the hook
319	    return null;
320	  }
321	}
322	
323	/**
324	 * Execute a hook plan: stage files, commit, sync.
325	 * Returns exit code and optional stderr for agent feedback.
326	 */
327	export function executePlan(
328	  plan: HookPlan,
329	  input: HookInput,
330	  state: RepoState,
331	): { exitCode: number; stderr?: string } {
332	  if (plan.action === "skip") return { exitCode: 0 };
333	
334	  if (plan.action === "commit-merge") {
335	    // Clock in and check who else is working
336	    const clockInMsg = plan.clockIn ? executeClockIn(plan.clockIn, input, state) : null;
337	
338	    // Stage the file if provided
339	    const filePath = input.tool_input.file_path;
340	    if (filePath) {
341	      execSync(`git add -- "${filePath}"`);
342	    }
343	    try {
344	      execSync(`git commit -m "${escapeForShell(plan.message)}"`);
345	    } catch (e: unknown) {
346	      // Let git's exit code pass through (e.g. 128 for unresolved merge paths)
347	      const code = getExitCode(e);
348	      return { exitCode: code, stderr: getStdout(e) };
349	    }
350	    if (plan.sync) {
351	      const syncResult = executeSync(plan.sync);
352	      if (syncResult.exitCode !== 0) return syncResult;
353	      if (clockInMsg) return { exitCode: 2, stderr: clockInMsg };
354	      return syncResult;
355	    }
356	    if (clockInMsg) return { exitCode: 2, stderr: clockInMsg };
357	    return { exitCode: 0 };
358	  }
359	
360	  // commit-and-sync
361	  const { commit, sync, clockIn: clockInPlan } = plan;
362	
363	  // Stage deletions
364	  for (const file of commit.filesToRemove) {
365	    try {
366	      execSync(`git -C "${state.repoRoot}" rm --cached --quiet -- "${file}"`, {
367	        stdio: "ignore",
368	      });
369	    } catch {
370	      // ignore
371	    }
372	  }
373	
374	  // Stage file edits
375	  for (const file of commit.filesToStage) {
376	    execSync(`git add -- "${file}"`);
377	  }
378	
379	  // Clock in and check who else is working
380	  const clockInMsg = clockInPlan ? executeClockIn(clockInPlan, input, state) : null;
381	
382	  // Check if there's anything staged (may have been a no-op)
383	  try {
384	    execSync("git diff --cached --quiet", { stdio: "ignore" });
385	    return { exitCode: 0 }; // nothing to commit
386	  } catch {
387	    // has staged changes — continue
388	  }
389	
390	  // Try to enrich commit message with task from transcript
391	  let finalCommit = commit;
392	  if (input.transcript_path) {
393	    const expanded = input.transcript_path.replace(/^~/, homedir());
394	    try {
395	      const content = readFileSync(expanded, "utf-8");
396	      const task = extractTaskFromTranscript(content);
397	      if (task) {
398	        finalCommit = buildCommitPlanWithTask(input, state, task);
399	      }
400	    } catch {
401	      // best-effort
402	    }
403	  }
404	
405	  // Commit
406	  if (finalCommit.body) {
407	    execSync(
408	      `git commit -m "${escapeForShell(finalCommit.subject)}" -m "${escapeForShell(finalCommit.body)}"`,
409	    );
410	  } else {
411	    execSync(`git commit -m "${escapeForShell(finalCommit.subject)}"`);
412	  }
413	
414	  // Snapshot transcript into the commit (opt-in via config)
415	  amendWithTranscriptSnapshot(input, state);
416	
417	  if (sync) {
418	    const syncResult = executeSync(sync);
419	    if (syncResult.exitCode !== 0) return syncResult;
420	    if (clockInMsg) return { exitCode: 2, stderr: clockInMsg };
421	    return syncResult;
422	  }
423	  if (clockInMsg) return { exitCode: 2, stderr: clockInMsg };
424	  return { exitCode: 0 };
425	}
426	
427	function amendWithTranscriptSnapshot(input: HookInput, state: RepoState): void {
428	  try {
429	    const config = readConfig(state.repoRoot);
430	    if (config.get("commit-transcripts") === "false") return;
431	    if (!input.transcript_path || !input.session_id) return;
432	
433	    const expanded = input.transcript_path.replace(/^~/, homedir());
434	    if (!existsSync(expanded)) return;
435	
436	    const snapshotDir = join(state.repoRoot, ".transcripts");
437	    mkdirSync(snapshotDir, { recursive: true });
438	    const shortSession = input.session_id.slice(0, 8);
439	    const epoch = Math.floor(Date.now() / 1000);
440	    const snapshotName = `${shortSession}-${epoch}.jsonl`;
441	    copyFileSync(expanded, join(snapshotDir, snapshotName));
442	
443	    execSync(`git add -- "${snapshotDir}"`, { cwd: state.repoRoot });
444	    execSync(`git commit --amend --no-edit`, { cwd: state.repoRoot });
445	  } catch {
446	    // best-effort — don't fail the hook if snapshot fails
447	  }
448	}
449	
450	export function executeSync(sync: SyncPlan): { exitCode: number; stderr?: string } {
451	  const { targetBranch, currentBranch } = sync;
452	
453	  // Pull from origin
454	  let targetBranchExistsUpstream = true;
455	  try {
456	    execSync(`git pull origin "${targetBranch}" --no-rebase 2>&1`, { encoding: "utf-8" });
457	  } catch (e: unknown) {
458	    const output = getStdout(e);
459	    if (!/couldn't find remote ref/.test(output)) {
460	      return conflictExit(output, targetBranch);
461	    }
462	    // Target branch doesn't exist on the remote yet — nothing to pull; the push below creates it.
463	    targetBranchExistsUpstream = false;
464	  }
465	
466	  // Merge local target branch into worktree branch
467	  if (targetBranchExistsUpstream && currentBranch && currentBranch !== targetBranch) {
468	    try {
469	      execSync(`git merge "${targetBranch}" --no-edit 2>&1`, { encoding: "utf-8" });
470	    } catch (e: unknown) {
471	      return conflictExit(getStdout(e), targetBranch);
472	    }
473	  }
474	
475	  // Push, retry once on failure
476	  try {
477	    execSync(`git push origin "HEAD:${targetBranch}" 2>&1`, { encoding: "utf-8" });
478	  } catch {
479	    // Retry: pull then push
480	    try {
481	      execSync(`git pull origin "${targetBranch}" --no-rebase 2>&1`, { encoding: "utf-8" });
482	    } catch (e: unknown) {
483	      return conflictExit(getStdout(e), targetBranch);
484	    }
485	    try {
486	      execSync(`git push origin "HEAD:${targetBranch}" 2>&1`, { encoding: "utf-8" });
487	    } catch (e: unknown) {
488	      return pushExit(getStdout(e), targetBranch);
489	    }
490	  }
491	
492	  // Keep local target branch in sync
493	  try {
494	    execSync(`git fetch origin "${targetBranch}:${targetBranch}" 2>/dev/null`);
495	  } catch {
496	    // If fetch fails (branch checked out), try ff-merge in the worktree
497	    try {
498	      const wtOutput = execSync(
499	        `git worktree list --porcelain`,
500	        { encoding: "utf-8" },
501	      );
502	      const mainWt = findWorktreeForBranch(wtOutput, targetBranch);
503	      if (mainWt) {
504	        try {
505	          execSync(
506	            `git -C "${mainWt}" merge --ff-only "origin/${targetBranch}" 2>/dev/null`,
507	          );
508	        } catch {
509	          // best-effort
510	        }
511	      }
512	    } catch {
513	      // ignore
514	    }
515	  }
516	
517	  return { exitCode: 0 };
518	}
519	
520	export function findWorktreeForBranch(porcelainOutput: string, branch: string): string | null {
521	  const blocks = porcelainOutput.split("\n\n");
522	  for (const block of blocks) {
523	    const lines = block.split("\n");
524	    let worktreePath = "";
525	    let branchRef = "";
526	    for (const line of lines) {
527	      if (line.startsWith("worktree ")) worktreePath = line.slice(9);
528	      if (line.startsWith("branch ")) branchRef = line.slice(7);
529	    }
530	    if (branchRef === `refs/heads/${branch}` && worktreePath) {
531	      return worktreePath;
532	    }
533	  }
534	  return null;
535	}
536	
537	function conflictExit(output: string, targetBranch: string): { exitCode: number; stderr: string } {
538	  return {
539	    exitCode: 2,
540	    stderr: `TRUNK-SYNC CONFLICT: ${HOOK_EXPLAINER} Another agent changed the same file, creating a merge conflict. The file now contains git conflict markers (<<<<<<< / ======= / >>>>>>>).\n\ngit output:\n${output}\n\nTo resolve:\n1. Read the conflicting file\n2. Edit it to the correct content (remove the <<<<<<< / ======= / >>>>>>> markers)\n3. Done — this hook will detect the merge state and complete the sync automatically on your next edit\n\nDo NOT run any git commands. The hook handles all git operations — your only job is to fix the file contents using Edit.`,
541	  };
542	}
543	
544	function pushExit(output: string, targetBranch: string): { exitCode: number; stderr: string } {
545	  return {
546	    exitCode: 2,
547	    stderr: `TRUNK-SYNC FAILED: ${HOOK_EXPLAINER} The push to remote failed.\n\ngit output:\n${output}\n\nTo resolve: run "git pull origin ${targetBranch} --no-rebase" then "git push origin HEAD:${targetBranch}". If there are conflicts, read the conflicting files and edit them to remove the conflict markers — the hook will complete the sync on your next edit.`,
548	  };
549	}
550	
551	function escapeForShell(s: string): string {
552	  return s.replace(/"/g, '\\"');
553	}
554	
555	function getExitCode(e: unknown): number {
556	  if (typeof e === "object" && e !== null && "status" in e) {
557	    const status = (e as { status: unknown }).status;
558	    if (typeof status === "number") return status;
559	  }
560	  return 1;
561	}
562	
563	function getStdout(e: unknown): string {
564	  if (typeof e === "object" && e !== null && "stdout" in e) {
565	    return String((e as { stdout: unknown }).stdout);
566	  }
567	  if (e instanceof Error) return e.message;
568	  return String(e);
569	}
